REELS=[
R(id="r1",time="11:00",theme="dark",tag="BUYING PROCESS",area="CALEDON",fmt="step-by-step (buying process, new-build warranty forms)",aud="buyer",
 hook="Caledon new build. Miss *this form?",kick="COVERAGE AT RISK",hprop="clipboard",hsay="Caledon new build: miss this form, risk coverage?",
 pts=[("30-Day Form","calendar","In your first 30 days of possession, send Tarion your 30-Day Form.","First, in your first thirty days of possession, send Tarion your thirty-day form."),
      ("List everything","clipboard","Only one is accepted, so list every unresolved item you have found.","Now the twist. Next, only one is accepted, so list every unresolved item you have found."),
      ("Year-End Form","calendar","In the last 30 days of year one, send the Year-End Form.","Then, in the last thirty days of your first year, send the year-end form."),
      ("Keep your proof","search","Filing starts a 120-day repair period. Keep dated photos and copies.","Finally, filing starts a one hundred twenty day repair period, so keep dated photos and copies.")],
 cta="Like, comment and *share with a new-build buyer",csay="Like, comment and share this with someone buying a new build. "+CTAW,
 fine="General information only. Not legal advice.",
 cap="Caledon new build. Miss this form?\n\nTarion says buyers of a new home in Ontario can use two key warranty forms. 1) Send the 30-Day Form during the first 30 days of possession. 2) Only one 30-Day Form is accepted, so list every unresolved item you have found. 3) Send the Year-End Form during the last 30 days of the first year of possession; Tarion calls it your final opportunity to report items covered by the one-year warranty. 4) Filing either form starts a 120-day builder repair period, so keep dated photos and copies. Your exact deadlines depend on your possession date.\nSource: Tarion, \"How to make a warranty claim and what to expect\" (tarion.com), checked Nov 22, 2026.\n\n"+CHK_B+"\n\nGeneral information only. Not legal advice.",
 tags="#caledon #peelregion #newhomebuyer #keyswithkrishna",
 pattern="6 tease + cost of a mistake",trigger="fear of losing warranty coverage by missing a deadline",share="a friend buying a new build"),
R(id="r2",time="15:00",theme="cream",tag="SELLER TIPS",area="MILTON",fmt="step-by-step (seller, lowball offer)",aud="seller",trial=True,
 hook="Milton lowball offer. *Ignore it?",kick="WAIT BEFORE REPLYING",hprop="handshake",hsay="Milton seller: lowball offer, ignore it?",
 pts=[("Read the whole offer","clipboard","Look past price: deposit, closing date and conditions count too.","First, look past the price. The deposit, closing date and conditions count too."),
      ("Compare sold prices","search","Ask your Realtor\u00ae to compare it to recent sold prices nearby.","Now the twist. Next, ask your Realtor to compare it with recent sold prices of similar homes nearby."),
      ("Consider a counter","handshake","A counter-offer lets you change price, dates and terms.","Then, remember a counter-offer lets you change the price, the dates and the terms."),
      ("Watch the deadline","calendar","Check how long the offer stays open before you reply.","Finally, check how long the offer stays open, so you reply before it expires.")],
 cta="Like, comment and *share with a Milton seller",csay="Like, comment and share this with someone selling in Milton. "+CTAW,
 fine="General information only. Not legal advice.",
 cap="Milton lowball offer. Ignore it?\n\nA low offer is not the end of the conversation. 1) Look past the price: the deposit, closing date and conditions count too. 2) Ask your Realtor\u00ae to compare it with recent sold prices of similar homes nearby. 3) A counter-offer lets you change the price, dates and terms. 4) Check how long the offer stays open before you reply. Talk it through with your Realtor\u00ae before you decide.\n\nSelling in Milton? "+INFO+"\n\nGeneral information only. Not legal advice.",
 tags="#miltonontario #haltonregion #sellingyourhome #keyswithkrishna",
 pattern="7 specific scene cold open + pain-point",trigger="worry about mishandling a low offer",share="a neighbour planning to sell"),
R(id="r3",time="19:00",theme="dark",tag="MONEY MATH",area="BRAMPTON",fmt="money-math (everyday, monthly mortgage on a $1M home with 20% down)",aud="buyer",series="money-math",math="everyday",
 hook="$1M Brampton home. Monthly mortgage?",kick="20% DOWN",hprop="calculator",hsay="A million dollar Brampton home. Monthly mortgage?",
 calc=[("Down payment, 20% of $1,000,000","$200,000","$1,000,000 x 20%","$200,000 down","piggy","First, twenty percent down on a million dollar home is two hundred thousand dollars."),
       ("Mortgage amount","$800,000","$1,000,000 - $200,000","$800,000 mortgage","house","Now the twist. Next, that leaves a mortgage of eight hundred thousand dollars."),
       ("Monthly mortgage at 4.64%, 25 years","$4,490","$800,000 at 4.64%, 25 years","$4,490 a month","calendar","Then, at four point six four percent over twenty-five years, that's about four thousand, four hundred ninety dollars a month.")],
 total=("Monthly mortgage, about","$4,490","Not included: property tax, insurance, utilities or maintenance.","Example only: $1M home, 20% down, $800,000 mortgage, 4.64% fixed (nesto.ca lowest 5-year fixed rate for 75-80% loan-to-value, as of Nov 20, 2026), 25-year amortization, Canadian semi-annual compounding, rate held for all 25 years. Rates change at renewal. Lenders also apply the stress test. Not mortgage, tax or legal advice.","Finally, that's the mortgage alone, so budget for property tax, insurance and utilities on top."),
 cta="Like, comment and *share with a Brampton buyer",csay="Like, comment and share this with a Brampton buyer. "+CTAW,
 fine="Example only. Not mortgage, tax or legal advice.",
 cap="$1M Brampton home. What is the monthly mortgage?\n\nExample only, computed with Canadian semi-annual compounding:\n1) 20% down on $1,000,000 = $200,000.\n2) Mortgage = $1,000,000 - $200,000 = $800,000.\n3) At 4.64% over a 25-year amortization, the monthly mortgage is about $4,490.\nThat is the mortgage only: property tax, home insurance, utilities and maintenance are extra. 4.64% is nesto.ca's lowest 5-year fixed rate for 75-80% loan-to-value as of Nov 20, 2026; your rate depends on your lender and profile, and rates change at renewal. Lenders also apply the stress test, so what you can afford is not the same as what you qualify for.\n\nWant help planning your budget? "+INFO+"\n\nExample only. Not mortgage, tax or legal advice.\nSource: nesto.ca 5-year fixed mortgage rates page, Nov 20, 2026.",
 tags="#bramptonrealestate #peelregion #mortgagetips #keyswithkrishna",
 pattern="11 number that demands explanation + 8 price anchor",trigger="curiosity about the real monthly number",share="a friend dreaming of a bigger home"),
R(id="r4",time="20:00",theme="cream",tag="BUYING PROCESS",area="OAKVILLE",fmt="step-by-step (moving in, Ontario address changes)",aud="buyer",
 hook="Moved to Oakville? Six-day *clock.",kick="BY LAW",hprop="movingbox",hsay="Moved to Oakville? A six-day clock is running.",
 pts=[("6-day deadline","calendar","Update your driver's licence and vehicle permit address within 6 days.","First, update the address on your driver's licence and vehicle permit within six days."),
      ("Health card","shield","Update your health card address within 30 days.","Now the twist. Next, your health card has a longer window: thirty days."),
      ("Permit pick-up","clipboard","Pick up your new permit at ServiceOntario. Bring the old one.","Then, collect your new vehicle permit at a ServiceOntario centre, and bring the old one."),
      ("Tell everyone else","mortgage","Then tell your bank, insurer and employer.","Finally, tell your bank, your insurer and your employer where you live now.")],
 cta="Like, comment and *share with a new homeowner",csay="Like, comment and share this with someone who just moved. "+CTAW,
 fine="General information only. Not legal advice.",
 cap="Moved to Oakville? Six-day clock.\n\nThe Government of Ontario says you must update your driver's licence and vehicle permit within 6 days of your address changing, and your health card within 30 days. 1) Update your driver's licence and vehicle permit address within 6 days; it is free online through a ServiceOntario account. 2) Update your health card address within 30 days. 3) Your new vehicle permit is picked up at a ServiceOntario centre, so bring the old one. 4) Then tell your bank, insurer and employer.\nSource: Government of Ontario, \"Change my address: Ontario services\" (ontario.ca), checked Nov 22, 2026.\n\n"+CHK_B+"\n\nGeneral information only. Not legal advice.",
 tags="#oakvillerealestate #haltonregion #movingtips #keyswithkrishna",
 pattern="7 specific scene cold open + 3 number",trigger="surprise at a short legal deadline",share="a friend who just moved"),
R(id="r5",time="21:00",theme="dark",tag="MYTH VS FACT",area="MISSISSAUGA",fmt="myth vs fact (mortgage term vs amortization)",aud="buyer",
 hook="5-year mortgage. *Paid off in five?",kick="TERM VS AMORTIZATION",hprop="mortgage",hsay="Mississauga: five-year mortgage, paid off in five?",
 pts=[("The myth","mortgage","Myth: a 5-year mortgage gets paid off in 5 years.","First, the myth: a five-year mortgage does not mean you're mortgage-free in five years."),
      ("What the term is","calendar","The term is how long your contract and rate last. Then you renew.","Now the twist. Next, the term is only how long your contract and rate last, and then you renew."),
      ("What amortization is","calculator","Amortization is the time to pay it all off, often 25 years.","Then, amortization is the time it takes to pay off the whole mortgage, often twenty-five years."),
      ("Plan for renewal","chart","Your rate can change at renewal. Start comparing before it ends.","Finally, your rate can change at renewal, so start comparing before your term ends.")],
 cta="Like, comment and *share with a first-time buyer",csay="Like, comment and share this with a Mississauga first-time buyer. "+CTAW,
 fine=GEN,
 cap="5-year mortgage. Paid off in five?\n\nNot quite. The Financial Consumer Agency of Canada says the mortgage term is the time your mortgage contract is in effect, while the amortization period is the time it takes to pay off the mortgage. 1) A 5-year term does not mean a 5-year payoff. 2) At the end of each term you renew. 3) Amortization is often 25 years; with less than 20% down the maximum is 30 years for first-time buyers or new builds, and 25 years in other cases. 4) Your rate can change at renewal, so compare options before your term ends.\nSource: Financial Consumer Agency of Canada, \"Mortgage terms and amortization\" (canada.ca), checked Nov 22, 2026.\n\nBuying in Mississauga? "+INFO+"\n\n"+GEN,
 tags="#mississaugarealestate #peelregion #mortgagetips #keyswithkrishna",
 pattern="1 contrarian/myth + 3 number that demands explanation",trigger="surprise at what a mortgage term really means",share="a friend shopping for a mortgage"),
R(id="r6",time="22:30",theme="cream",tag="QUICK TIP",area="GEORGETOWN",fmt="quick-tip (radon test)",aud="buyer",
 hook="Georgetown basement. *Radon tested?",kick="3-MONTH TEST",hprop="search",hsay="Georgetown basement: has it been tested for radon?",
 pts=[("Radon test","search","Radon is invisible. Health Canada says test at least 3 months.","Quick tip: radon is invisible, so Health Canada says to test for at least three months, ideally in fall or winter.")],
 cta="Like, comment and *share with a Georgetown buyer",csay="Like, comment and share this with a Georgetown buyer. "+CTAW,
 fine=GEN,
 cap="Georgetown basement. Radon tested?\n\nQuick tip: radon is a radioactive gas you cannot see, smell or taste. Health Canada's guideline is 200 Bq/m\u00b3 and recommends a long-term test of at least three months, ideally in the fall or winter, placed in the lowest level where you spend time. Ask the seller if the home has ever been tested, and ask your Realtor\u00ae or home inspector how to arrange a test.\nSource: Health Canada, \"Radon: what you need to know\" and \"Radon reduction guide for Canadians\" (canada.ca), checked Nov 22, 2026.\n\nBuying in Georgetown? "+INFO+"\n\n"+GEN,
 tags="#georgetownontario #haltonhills #homebuyingtips #keyswithkrishna",
 pattern="4 direct address with a stake",trigger="worry about an invisible health risk",share="a friend buying a home with a basement"),
]
